/**
 * Version of the room contract (state definition and message types).
 * Raise it whenever a change to the contract breaks older frontends.
 */
export const CONTRACT_VERSION = 2;

/** The name under which the Room type is registered. */
export const ROOM_NAME = "collaboration";

/** The options a client passes when creating or joining a Room. */
export type JoinOptions = {
  /** The client's CONTRACT_VERSION. */
  contractVersion: number;
  /** The display name, typed by the person. Ignored while login is on: the name then comes from the login. */
  name?: string;
  /** Only when creating: the Room's name; none if left out or empty. */
  roomName?: string;
  /** Only when creating: who may find the Room (see RoomVisibility); "public" if left out. */
  visibility?: RoomVisibility;
  /**
   * Only when creating: the creator's own exploration, which becomes the
   * Room's. Each capability adds its part.
   */
  startingState?: StartingState;
};

/**
 * Who may find a Room: "public" Rooms are listed by GET /rooms; "code" Rooms
 * are not, and only someone with the room code joins them. Set when creating,
 * fixed for the Room's life.
 */
export type RoomVisibility = "public" | "code";

/** A public Room as GET /rooms lists it. */
export type RoomListing = {
  /** The code to join the Room with. */
  roomCode: string;
  /** The Room's name; "" if it has none. */
  roomName: string;
  /** The display name of the Room's Landscape; "" if unknown. */
  landscapeName: string;
  /** The display name of the Host. */
  hostName: string;
  /** How many Participants are in the Room. */
  users: number;
};

/** The creator's own exploration, handed over to a new Room. */
export type StartingState = {
  /** The value of the Landscape token being explored. */
  landscapeToken?: string;
  /** Human-readable Landscape name for room discovery. */
  landscapeName?: string;
  /** The closed and hidden Districts. */
  districts?: DistrictLists;
  /** The ids of the highlighted entities; they become the creator's highlights. */
  highlights?: string[];
  /** All annotations, open or minimized. */
  annotations?: StartingAnnotation[];
};

/**
 * Error codes with which the service refuses to create or join a Room.
 * The SDK rejects `create` / `joinById` with an error carrying the code.
 */
export const JoinRefusal = {
  /** No live Room has this code (Colyseus' own code). */
  UNKNOWN_ROOM: 522,
  /** The client was built against another CONTRACT_VERSION. */
  CONTRACT_MISMATCH: 4100,
  /** The Room already has its maximum number of Participants. */
  ROOM_FULL: 4101,
  /** Login is on and the request carried no valid login token. */
  LOGIN_REQUIRED: 4102,
} as const;

/**
 * Close codes with which the service removes a Participant from a Room.
 * The SDK passes the code to `room.onLeave`. A removed Participant must not
 * be offered reconnection.
 */
export const LeaveCode = {
  /** The Host kicked the Participant. They may rejoin with the room code. */
  KICKED: 4011,
} as const;

/**
 * The longest entity id (of a District, building, communication, ...) the
 * service accepts in any message. Longer than any id the frontend makes, and
 * short enough that every message naming one entity stays far below 4 KB.
 */
export const MAX_ENTITY_ID_LENGTH = 1000;

/** Whether a message's value is an entity id the service accepts: a non-empty string of at most MAX_ENTITY_ID_LENGTH characters. */
export function isEntityId(value: unknown): value is string {
  return typeof value === "string" && value !== "" && value.length <= MAX_ENTITY_ID_LENGTH;
}

/** A Room keeps this many chat entries; the oldest are dropped beyond that. */
export const CHAT_HISTORY_LIMIT = 200;

/** The longest chat message, in characters, after trimming. */
export const MAX_CHAT_MESSAGE_LENGTH = 1000;

/**
 * What a chat entry is. Participants post messages; the service writes
 * entries of other kinds itself (e.g. ping and highlight events).
 */
export const ChatEntryKind = {
  /** A message a Participant posted. */
  MESSAGE: "message",
  /** Written by the service when a Participant pinged an entity or a position. */
  PING: "ping",
  /** Written by the service when an entity became a Participant's highlight. */
  HIGHLIGHT: "highlight",
} as const;
export type ChatEntryKind = (typeof ChatEntryKind)[keyof typeof ChatEntryKind];

/**
 * Reasons with which the service rejects a chat request. The SDK rejects
 * `room.request(...)` with an error whose `reason` is one of these.
 */
export const ChatRefusal = {
  /** The sender is muted by the Host. */
  MUTED: "muted",
  /** Only the Host (or, for deletion, the author) may do this. */
  NOT_ALLOWED: "not_allowed",
  /** The payload is malformed, empty, too long, or names nothing known. */
  INVALID: "invalid",
} as const;
export type ChatRefusal = (typeof ChatRefusal)[keyof typeof ChatRefusal];

/**
 * One change to the closed and hidden Districts. A user action (a click)
 * becomes one list of these, sent as one "districts" message and applied as a
 * whole, so two Participants acting at once never interleave.
 *
 * Which Districts a click concerns (children, nested ones, a city) is worked
 * out by the frontend, which knows the Landscape; the service does not. So
 * "close all" names only the top-level Districts, and the closed and hidden
 * sets can be inverted (see DistrictIdSet), keeping every message small.
 */
export type DistrictAction =
  | { type: "open"; ids: string[] }
  | { type: "close"; ids: string[] }
  | { type: "show"; ids: string[] }
  | { type: "hide"; ids: string[] }
  /** Opens and shows every District. */
  | { type: "openAll" }
  /** Closes every District and hides every one but these top-level Districts, which are shown. */
  | { type: "closeAll"; topLevelIds: string[] };

/**
 * The closed and hidden Districts as plain lists of District ids. An inverted
 * list names the exceptions: with `closedInverted`, every District of the
 * Landscape is closed except those in `closed` (likewise for hidden).
 */
export type DistrictLists = {
  closed: string[];
  hidden: string[];
  closedInverted?: boolean;
  hiddenInverted?: boolean;
};

/**
 * The Host's switch of the District sharing option. Switching it off changes
 * nobody's view: everyone takes the Room's Districts as their own. Switching
 * it on makes the Host's own Districts the Room's, so it carries them.
 */
export type DistrictSharing = { shared: false } | { shared: true; districts: DistrictLists };

/**
 * What `applyDistrictActions` changes: a set of District ids. While
 * `inverted`, it holds every District of the Landscape except the ids in it.
 */
export type DistrictIdSet = {
  add(id: string): unknown;
  delete(id: string): unknown;
  clear(): void;
  inverted: boolean;
};

const include = (set: DistrictIdSet, ids: readonly string[]) => {
  for (const id of ids) {
    if (set.inverted) set.delete(id);
    else set.add(id);
  }
};
const exclude = (set: DistrictIdSet, ids: readonly string[]) => {
  for (const id of ids) {
    if (set.inverted) set.add(id);
    else set.delete(id);
  }
};
const fill = (set: DistrictIdSet, all: boolean) => {
  set.clear();
  set.inverted = all;
};

/**
 * The meaning of the District actions. The same function changes the
 * person's own Districts in the browser when alone and the Room's in the
 * service.
 */
export function applyDistrictActions(
  districts: { closed: DistrictIdSet; hidden: DistrictIdSet },
  actions: readonly DistrictAction[],
): void {
  for (const action of actions) {
    switch (action.type) {
      case "open":
        exclude(districts.closed, action.ids);
        break;
      case "close":
        include(districts.closed, action.ids);
        break;
      case "show":
        exclude(districts.hidden, action.ids);
        break;
      case "hide":
        include(districts.hidden, action.ids);
        break;
      case "openAll":
        fill(districts.closed, false);
        fill(districts.hidden, false);
        break;
      case "closeAll":
        fill(districts.closed, true);
        fill(districts.hidden, true);
        exclude(districts.hidden, action.topLevelIds);
        break;
    }
  }
}

/** Replaces the Districts with these lists. */
export function replaceDistricts(
  districts: { closed: DistrictIdSet; hidden: DistrictIdSet },
  lists: DistrictLists,
): void {
  fill(districts.closed, lists.closedInverted === true);
  fill(districts.hidden, lists.hiddenInverted === true);
  for (const id of lists.closed) districts.closed.add(id);
  for (const id of lists.hidden) districts.hidden.add(id);
}

/**
 * One user action on the highlights, sent as one "highlights" message. An
 * entity has at most one highlighter: highlighting an entity somebody else
 * highlighted takes it over. Removing touches only the actor's own highlights,
 * so removing another Participant's highlight takes two clicks.
 */
export type HighlightAction =
  /** The entity becomes the actor's highlight, whoever had it before. */
  | { type: "highlight"; entityId: string }
  /** The actor's highlight of the entity is removed; anyone else's stays. */
  | { type: "unhighlight"; entityId: string }
  /** A click: removes the actor's own highlight of the entity, else highlights it (taking it over). */
  | { type: "toggle"; entityId: string }
  /** Removes every highlight of the actor; everyone else's stay. */
  | { type: "unhighlightAll" }
  /**
   * Many entities become the actor's highlights at once (each taken over).
   * With `replaceOwn`, the actor's other highlights are removed first. A long
   * list is sent in chunks (see highlightChunks); every chunk after the first
   * is `continued`, so the whole action gets one highlight chat entry.
   */
  | { type: "highlightMany"; entityIds: string[]; replaceOwn?: boolean; continued?: boolean }
  /** The actor's highlights of these entities are removed; anyone else's stay. */
  | { type: "unhighlightMany"; entityIds: string[] };

/** The most UTF-8 bytes of entity ids in one highlight message, so each stays far below 4 KB. */
const MAX_CHUNK_BYTES = 3000;

/**
 * A list of entity ids split into the chunks of one bulk highlight action,
 * each small enough for one message. An id is never split.
 */
export function highlightChunks(entityIds: readonly string[]): string[][] {
  const encoder = new TextEncoder();
  const chunks: string[][] = [];
  let chunk: string[] = [];
  let bytes = 0;
  for (const entityId of entityIds) {
    // The id plus quotes and separator.
    const size = encoder.encode(entityId).length + 3;
    if (chunk.length > 0 && bytes + size > MAX_CHUNK_BYTES) {
      chunks.push(chunk);
      chunk = [];
      bytes = 0;
    }
    chunk.push(entityId);
    bytes += size;
  }
  if (chunk.length > 0) chunks.push(chunk);
  return chunks;
}

/** What `applyHighlightAction` changes: entity id -> the highlighter. */
export type HighlightOwners = {
  get(entityId: string): string | undefined;
  set(entityId: string, highlighter: string): unknown;
  delete(entityId: string): unknown;
  forEach(callback: (highlighter: string, entityId: string) => void): void;
};

/**
 * The meaning of a highlight action by `actor`. The same function changes the
 * person's own highlights in the browser when alone (where every highlight is
 * the person's) and the Room's in the service.
 */
export function applyHighlightAction(highlights: HighlightOwners, actor: string, action: HighlightAction): void {
  switch (action.type) {
    case "highlight":
      highlights.set(action.entityId, actor);
      break;
    case "unhighlight":
      if (highlights.get(action.entityId) === actor) highlights.delete(action.entityId);
      break;
    case "toggle":
      if (highlights.get(action.entityId) === actor) highlights.delete(action.entityId);
      else highlights.set(action.entityId, actor);
      break;
    case "unhighlightAll":
      removeOwn(highlights, actor);
      break;
    case "highlightMany":
      if (action.replaceOwn) removeOwn(highlights, actor);
      for (const entityId of action.entityIds) highlights.set(entityId, actor);
      break;
    case "unhighlightMany":
      for (const entityId of action.entityIds) {
        if (highlights.get(entityId) === actor) highlights.delete(entityId);
      }
      break;
  }
}

function removeOwn(highlights: HighlightOwners, actor: string) {
  const own: string[] = [];
  highlights.forEach((highlighter, entityId) => {
    if (highlighter === actor) own.push(entityId);
  });
  for (const entityId of own) highlights.delete(entityId);
}

/** The longest annotation title, in characters. */
export const MAX_ANNOTATION_TITLE_LENGTH = 200;

/** The longest annotation text, in characters. */
export const MAX_ANNOTATION_TEXT_LENGTH = 10_000;

/**
 * What a person writes in an annotation. `entityId` names the annotated
 * entity of the Landscape; an annotation without one is free.
 */
export type AnnotationContent = {
  entityId?: string;
  title: string;
  text: string;
};

/** One annotation of the creator, handed over to a new Room as it is. */
export type StartingAnnotation = AnnotationContent & {
  /** A positive whole number, unique among the creator's annotations. */
  id: number;
  creatorName: string;
  lastEditorName: string;
};

/** The service's answer to an "annotationAdd" request: the annotation's id. */
export type AnnotationAdded = { id: number };

/**
 * Reasons with which the service rejects an "annotationAdd" request. The SDK
 * rejects `room.request(...)` with an error whose `reason` is one of these.
 */
export const AnnotationRefusal = {
  /** The payload is malformed, or the title or text is too long. */
  INVALID: "invalid",
} as const;
export type AnnotationRefusal = (typeof AnnotationRefusal)[keyof typeof AnnotationRefusal];

type Clearable = { clear(): void };

/** The parts of the Room state that name entities of its Landscape. */
export type LandscapeBoundState = {
  districts: { closed: Clearable; hidden: Clearable; closedInverted: boolean; hiddenInverted: boolean };
  highlights: Clearable;
  popups: Clearable;
  annotations: Clearable;
};

/**
 * Everything in the Room that is tied to its Landscape, cleared on a
 * Landscape switch: every District open and shown, no highlights, shared
 * popups or annotations. The rest of the Room (Participants, Host, chat
 * history, mutes, the District sharing option) stays.
 *
 * A capability whose Room state names entities of the Landscape adds its
 * line here.
 */
export function clearLandscapeState(state: LandscapeBoundState): void {
  state.districts.closed.clear();
  state.districts.hidden.clear();
  state.districts.closedInverted = false;
  state.districts.hiddenInverted = false;
  state.highlights.clear();
  state.popups.clear();
  state.annotations.clear();
}

/**
 * Messages a client sends to the Room: message type -> payload.
 * Each entry has a handler of the same name in CollaborationRoom's `messages`.
 * A Participant is always named by their session id, in a field `sessionId`.
 */
export type ClientMessages = {
  /** Host only: removes the Participant with this session id from the Room. */
  kick: { sessionId: string };
  /** Host only: makes the Participant with this session id the Host instead. */
  handOverHost: { sessionId: string };
  /** Changes the sender's own color to a CSS hex color such as "#e6194b". Other values are ignored. */
  setColor: { color: string };
  /** Post a chat message. Rejected with a ChatRefusal (e.g. "muted"). */
  chatSend: { text: string };
  /** Delete a chat entry for everyone. Allowed for its author and the Host. */
  chatDelete: { entryId: string };
  /** Host only: mutes or unmutes the Participant with this session id. */
  chatMute: { sessionId: string; muted: boolean };
  /** Follow another Participant's camera (their session id), or stop with null. */
  spectate: { target: string | null };
  /**
   * The sender's camera, sent only while somebody spectates them, at most
   * CAMERA_UPDATES_PER_SECOND times per second and only when it changed.
   */
  camera: CameraPose;
  /** The sender entered the immersive view of this entity, or left it with null. */
  immersive: { entityId: string | null };
  /**
   * Host only: the Room explores this Landscape (a Landscape token value)
   * from now on. Clears everything tied to the old Landscape.
   */
  switchLandscape: { landscapeToken: string; landscapeName?: string };
  /** One user action on the Districts (see DistrictAction). */
  districts: DistrictAction[];
  /** Host only: switches the District sharing option (see DistrictSharing). */
  districtSharing: DistrictSharing;
  /**
   * One user action on the highlights (see HighlightAction). An entity that
   * becomes the sender's highlight gets a highlight chat entry.
   */
  highlights: HighlightAction;
  /** Pings a spot for the others (see Ping). Nothing is stored but a ping chat entry. */
  ping: Ping;
  /** Shares the sender's popup of this entity: everyone in the Room has it open from now on. */
  sharePopup: { entityId: string };
  /** Closes the shared popup of this entity for everyone. Allowed for any Participant. */
  closePopup: { entityId: string };
  /**
   * A request: makes a new annotation, by the sender. Answered with its
   * AnnotationAdded id; for an entity that already has one, with the id of
   * that one, and nothing changes. Rejected with an AnnotationRefusal.
   */
  annotationAdd: AnnotationContent;
  /** Saves an annotation's title and text, with the sender as last editor. Sent on save, not per keystroke. */
  annotationEdit: { id: number; title: string; text: string };
  /** Removes an annotation for everyone. */
  annotationRemove: { id: number };
};

/**
 * Messages the Room sends to clients: message type -> payload.
 */
export type ServerMessages = {
  /** The camera of the Participant `from`, forwarded only to those who spectate them. */
  camera: CameraPose & { from: string };
  /** Another Participant's ping, to be shown in their color (`from` is their session id). */
  ping: Required<Ping> & { from: string; color: string };
};

/**
 * A pinged spot: a world position [x, y, z], and the entity there if the
 * Participant pinged one ("" or left out for a bare position).
 */
export type Ping = {
  entityId?: string;
  position: [number, number, number];
};

/** A camera as world-space pose plus the column-major 4x4 projection matrix (as three.js `toArray()`). */
export type CameraPose = {
  position: [number, number, number];
  quaternion: [number, number, number, number];
  projection: number[];
};

/** How often a spectated Participant sends its camera at most. */
export const CAMERA_UPDATES_PER_SECOND = 30;

// Room state, as plain snapshot types.

export type CollaborationState = {
  participants: Record<string, Participant>;
  hostId: string;
  landscapeToken: string;
  roomName: string;
  landscapeName: string;
  visibility: string;
  chat: ChatEntry[];
  districts: Districts;
  highlights: Record<string, string>;
  popups: Record<string, SharedPopup>;
  annotations: Record<string, Annotation>;
};

export type Participant = {
  name: string;
  color: string;
  muted: boolean;
  spectating: string;
  immersiveEntityId: string;
};

export type ChatEntry = {
  id: string;
  kind: string;
  authorId: string;
  authorName: string;
  authorColor: string;
  text: string;
  entityId: string;
  entityCount: number;
  position: number[];
  time: number;
};

export type Districts = {
  shared: boolean;
  closed: Record<string, boolean>;
  hidden: Record<string, boolean>;
  closedInverted: boolean;
  hiddenInverted: boolean;
};

export type SharedPopup = {
  sharedById: string;
  sharedByName: string;
};

export type Annotation = {
  id: number;
  entityId: string;
  title: string;
  text: string;
  creatorName: string;
  lastEditorName: string;
};
